begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','budget-a@example.test'),('10000000-0000-4000-8000-000000000002','budget-b@example.test');
insert into auth.sessions(id,user_id) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into finance.profiles(id,display_name) values ('10000000-0000-4000-8000-000000000001','Synthetic A'),('10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.households(id,name) values ('30000000-0000-4000-8000-000000000001','Synthetic A'),('30000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.household_members(id,household_id,user_id,display_name) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A'),('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B');
create function pg_temp.command() returns jsonb language sql as $$select '{"id":"50000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","month":"2026-10","scope":{"kind":"TOTAL","memberId":null,"categoryId":null},"planned":{"amount":"100","currency":"ILS"},"action":"CREATE","expectedVersion":0,"idempotencyKey":"synthetic-budget-command"}'::jsonb$$;
select ok(not has_function_privilege('anon','api.save_budget(jsonb)','EXECUTE'),'anonymous command denied');
select ok(not has_function_privilege('anon','api.budget_snapshot()','EXECUTE'),'anonymous snapshot denied');
select ok(not has_table_privilege('authenticated','finance.budget_revisions','INSERT'),'no direct revision insert');
select ok(not has_table_privilege('authenticated','finance.budgets','UPDATE'),'no direct head update');
select ok(not has_table_privilege('authenticated','private.budget_receipts','SELECT'),'private receipts hidden');
select ok(not prosecdef and provolatile='s','stable invoker snapshot') from pg_proc where oid='api.budget_snapshot()'::regprocedure;
select is((select proconfig[1] from pg_proc where oid='private.save_budget(jsonb)'::regprocedure),'search_path=""','empty search path');
set local role anon;
select throws_ok('select api.budget_snapshot()','42501',null,'anonymous call denied');
set local role authenticated;
select is(api.save_budget(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','missing live session command denied');
select is(api.budget_snapshot()->'error'->>'code','NOT_AUTHORIZED','missing live session read denied');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.save_budget(pg_temp.command())->>'ok','true','create explicit plan');
select is(api.save_budget(pg_temp.command())->>'version','1','identical retry same version');
select is((select count(*) from finance.budget_revisions),1::bigint,'one immutable revision');
select is(api.save_budget(jsonb_set(pg_temp.command(),'{planned,amount}','"101"'))->'error'->>'code','CONFLICT','changed payload same key denied');
select is(api.save_budget(pg_temp.command()||'{"id":"50000000-0000-4000-8000-000000000002","idempotencyKey":"synthetic-budget-other"}')->'error'->>'code','CONFLICT','duplicate TOTAL scope rejected');
select is(api.save_budget(pg_temp.command()||'{"householdId":"30000000-0000-4000-8000-000000000002"}')->'error'->>'code','NOT_AUTHORIZED','forged household denied');
select is(api.save_budget(pg_temp.command()||'{"id":"50000000-0000-4000-8000-000000000003","idempotencyKey":"synthetic-budget-forged","scope":{"kind":"MEMBER","memberId":"40000000-0000-4000-8000-000000000002","categoryId":null}}')->'error'->>'code','INVALID_INPUT','foreign member denied');
select is(api.save_budget(pg_temp.command()||'{"id":"50000000-0000-4000-8000-000000000003","idempotencyKey":"synthetic-budget-forged","scope":{"kind":"ALL","memberId":null,"categoryId":"60000000-0000-4000-8000-000000000002"}}')->'error'->>'code','INVALID_INPUT','unknown category denied');
select is(api.save_budget(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"idempotencyKey":"synthetic-budget-edit","planned":{"amount":"0","currency":"ILS"}}')->>'version','2','explicit zero edit');
select is(api.save_budget(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"idempotencyKey":"synthetic-budget-stale"}')->'error'->>'code','CONFLICT','stale edit denied');
select is(api.save_budget(pg_temp.command())->>'version','1','old original receipt retained after edit');
select is(api.save_budget(pg_temp.command()||'{"action":"ARCHIVE","expectedVersion":2,"idempotencyKey":"synthetic-budget-archive","planned":{"amount":"0","currency":"ILS"}}')->>'version','3','archive appends revision');
select is((select count(*) from finance.budget_revisions),3::bigint,'full history retained');
select is(api.budget_snapshot()->'snapshot'->>'size','3','bounded explicit plan snapshot size');
select is(api.budget_snapshot()->'snapshot'->'revisions'->0->>'actorMemberId','40000000-0000-4000-8000-000000000001','durable author');
select is(api.save_budget(pg_temp.command()||'{"action":"EDIT","expectedVersion":3,"idempotencyKey":"synthetic-budget-reactivate"}')->'error'->>'code','CONFLICT','archive terminal');
select throws_ok($$update finance.budgets set status='ACTIVE'$$,'42501',null,'direct updates denied');
select throws_ok($$delete from finance.budget_revisions$$,'42501',null,'direct delete denied');
select throws_ok($$select * from private.budget_audit$$,'42501',null,'indirect audit denied');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is((select count(*) from finance.budget_revisions),0::bigint,'household B cannot read A plans');
select is(jsonb_array_length(api.budget_snapshot()->'snapshot'->'revisions'),0,'invoker snapshot isolates B');
reset role;
select throws_ok($$update finance.budget_revisions set body=body$$,'23514',null,'immutable history even privileged update');
select is((select count(*) from private.budget_audit),3::bigint,'one atomic audit per version');
select is((select count(*) from private.budget_receipts),3::bigint,'one receipt per successful command');
select throws_ok($$insert into finance.budgets values('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000099','2026-10-01','MEMBER','40000000-0000-4000-8000-000000000002',null,'ILS',1,'ACTIVE')$$,'23503',null,'independent composite member FK');
insert into finance.categories values('60000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002',1,'{"id":"60000000-0000-4000-8000-000000000002","householdId":"30000000-0000-4000-8000-000000000002","version":1,"name":"Synthetic foreign category","kind":"EXPENSE","status":"ACTIVE"}');
select throws_ok($$insert into finance.budgets values('30000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000099','2026-10-01','ALL',null,'60000000-0000-4000-8000-000000000002','ILS',1,'ACTIVE')$$,'23503',null,'independent composite category FK');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
savepoint bounds;
insert into finance.budget_revisions(household_id,id,version,actor_member_id,body)
select household_id,id,v,actor_member_id,body||jsonb_build_object('version',v) from finance.budget_revisions cross join generate_series(4,10004) v where version=1;
set local role authenticated;
select is(api.budget_snapshot()->'error'->>'code','INVALID_INPUT','over 10000 revisions fail explicitly');
select ok(not api.budget_snapshot()?'snapshot','no truncated budget snapshot');
reset role;
rollback to bounds;
savepoint bytes;
insert into finance.budget_revisions(household_id,id,version,actor_member_id,body)
select household_id,id,v,actor_member_id,body||jsonb_build_object('version',v) from finance.budget_revisions cross join generate_series(4,9003) v where version=1;
select is(api.create_account('{"account":{"id":"70000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","name":"Synthetic observations","ownership":{"kind":"HOUSEHOLD"},"type":"INVESTMENT","currency":"ILS","valuationCurrency":"ILS","balancePolicy":"OBSERVED","status":"ACTIVE"},"version":1,"manualSourceId":"80000000-0000-4000-8000-000000000001"}'::jsonb)->>'ok','true','combined-bound fixture');
insert into finance.balance_observations(id,household_id,account_id,source_id,observation_date,amount,currency,coverage,note)
select gen_random_uuid(),'30000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001',date '1000-01-01'+v,1,'ILS','COMPLETE',repeat('s',500) from generate_series(1,16000) v;
set local role authenticated;
select is(api.reporting_snapshot()->>'ok','true','nested report alone below byte bound');
select is(api.budget_snapshot()->'error'->>'code','INVALID_INPUT','combined budget/report bytes exceed 16 MiB below row bounds');
select ok(not api.budget_snapshot()?'snapshot','byte overflow returns no partial success');
reset role;
rollback to bytes;
update finance.household_members set status='REVOKED' where id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.save_budget(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','revoked unchanged JWT cannot replay receipt');
select is(jsonb_array_length(api.budget_snapshot()->'snapshot'->'revisions'),0,'revocation hides plan history');
reset role;
delete from auth.sessions where id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is(api.budget_snapshot()->'error'->>'code','NOT_AUTHORIZED','deleted session denies read');
reset role;
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
select is((select count(*) from finance.budget_revisions),3::bigint,'author deletion retains decisions');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.save_budget(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','deleted Auth user command denied');
select * from finish();
rollback;
